    27	// Map ENDTOEND event format to RawEventInput
    28	function mapToRawEventInput(event: any, source: string): RawEventInput {
    29	  return {
    30	    source,
    31	    source_id: event.id,
    32	    title: event.title,
    33	    description: event.description || '',
    34	    start_date: event.date,
    35	    start_time: event.time,
    36	    end_date: event.date,
    37	    end_time: event.time,
    38	    venue_name: event.venue,
    39	    venue_city: event.area || 'Stockholm',
    40	    venue_address: event.address || '',
    41	    venue_lat: event.lat || null,
    42	    venue_lng: event.lng || null,
    43	    category: event.category || 'culture',
    44	    url: event.url || '',
    45	    image_url: event.image_url || event.imageUrl || null,
    46	    price_info: event.price_info || event.priceInfo || null,
    47	    promoter: event.promoter || null,
    48	    organizer: event.organizer || null,
    49	    accessibility: event.accessibility || null,
    50	    age_restriction: event.age_restriction || event.ageRestriction || null,
    51	    tags: event.tags || [],
    52	    raw_data: event,
    53	  };
    54	}
