    56	// Queue events from any source
    57	async function queueEvents(events: any[], source: string): Promise<number> {
    58	  let queued = 0;
    59	  for (const event of events) {
    60	    try {
    61	      const rawEvent = mapToRawEventInput(event, source);
    62	      await rawEventsQueue.add('process-raw-event', rawEvent, {
    63	        jobId: `${source}:${event.id}`,
    64	      });
    65	      queued++;
    66	    } catch (err) {
    67	      console.error(`[${source}] Failed to queue event ${event.id}:`, err);
    68	    }
    69	  }
    70	  return queued;
    71	}
