    73	// Run a single source
    74	export async function runSource(
    75	  name: string,
    76	  fetchFn: () => Promise<any[]>,
    77	  options?: { filterFn?: (e: any) => boolean }
    78	): Promise<SourceResult> {
    79	  console.log(`[sources] Running source: ${name}`);
    80	  const result: SourceResult = {
    81	    source: name,
    82	    eventsQueued: 0,
    83	    eventsFound: 0,
    84	    errors: [],
    85	    status: 'success',
    86	  };
    87	
    88	  try {
    89	    const events = await fetchFn();
    90	    result.eventsFound = events.length;
    91	    
    92	    const filtered = options?.filterFn 
    93	      ? events.filter(options.filterFn) 
    94	      : events;
    95	    
    96	    if (filtered.length < events.length) {
    97	      console.log(`[${name}] Filtered ${events.length - filtered.length} events`);
    98	    }
    99	    
   100	    result.eventsQueued = await queueEvents(filtered, name);
   101	    
   102	    if (result.eventsQueued === 0 && result.eventsFound > 0) {
   103	      result.status = 'partial';
   104	    }
   105	  } catch (err: any) {
   106	    result.errors.push(err.message || String(err));
   107	    result.status = 'fail';
   108	    console.error(`[${name}] Error:`, err);
   109	  }
   110	
   111	  return result;
   112	}
